CREATE TABLE IF NOT EXISTS public.alerts (
  asset_id TEXT,
  channel TEXT,
  condition_type TEXT NOT NULL,
  created_at TIMESTAMPTZ,
  frequency TEXT,
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  is_active BOOLEAN,
  last_triggered_at TIMESTAMPTZ,
  name TEXT NOT NULL,
  threshold_value NUMERIC,
  user_id UUID NOT NULL
);

CREATE TABLE IF NOT EXISTS public.api_keys (
  created_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  is_active BOOLEAN,
  key_hash TEXT NOT NULL,
  key_prefix TEXT NOT NULL,
  last_used_at TIMESTAMPTZ,
  name TEXT NOT NULL,
  permissions JSONB,
  user_id UUID NOT NULL
);

CREATE TABLE IF NOT EXISTS public.audit_log (
  action TEXT NOT NULL,
  created_at TIMESTAMPTZ,
  details JSONB,
  entity_id TEXT,
  entity_type TEXT,
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ip_address TEXT NOT NULL,
  organization_id UUID,
  user_id UUID
);

CREATE TABLE IF NOT EXISTS public.bans (
  created_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  moderator_id UUID NOT NULL,
  reason TEXT,
  user_id UUID NOT NULL
);

CREATE TABLE IF NOT EXISTS public.carbon_credits (
  created_at TIMESTAMPTZ,
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id TEXT,
  quantity NUMERIC NOT NULL,
  retirement_account TEXT,
  retirement_beneficiary TEXT,
  retirement_beneficiary_harmonized TEXT,
  retirement_note TEXT,
  retirement_reason TEXT,
  transaction_date TIMESTAMPTZ,
  transaction_type TEXT,
  vintage INTEGER
);

CREATE TABLE IF NOT EXISTS public.carbon_projects (
  category TEXT,
  country TEXT NOT NULL,
  created_at TIMESTAMPTZ,
  first_issuance_at TIMESTAMPTZ,
  first_retirement_at TIMESTAMPTZ,
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  is_compliance BOOLEAN,
  issued NUMERIC,
  listed_at TIMESTAMPTZ,
  name TEXT NOT NULL,
  project_id TEXT NOT NULL,
  project_type TEXT,
  project_type_source TEXT,
  project_url TEXT,
  proponent TEXT,
  protocol TEXT,
  registry TEXT,
  retired NUMERIC,
  status TEXT
);

CREATE TABLE IF NOT EXISTS public.comments (
  author_id UUID NOT NULL,
  challenge_id UUID,
  content TEXT NOT NULL,
  created_at TIMESTAMPTZ,
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  is_deleted BOOLEAN,
  karma INTEGER,
  parent_id UUID,
  post_id UUID,
  updated_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS public.karma_transactions (
  amount NUMERIC NOT NULL,
