  company_sector TEXT,
  company_size TEXT,
  company_tagline TEXT,
  company_website TEXT,
  created_at TIMESTAMPTZ,
  display_name TEXT,
  expertise_areas TEXT[],
  headline TEXT,
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  karma INTEGER,
  linkedin_url TEXT,
